@push('scripts')<script>$(function(){$('.js-billing-action').on('click',function(){var b=$(this);var options={title:b.data('action')==='issue'?'ออกใบวางบิล?':'ยกเลิกใบวางบิล?',icon:'warning',showCancelButton:true,confirmButtonText:'ยืนยัน',cancelButtonText:'กลับ'};if(b.data('action')==='cancel'){options.input='textarea';options.inputLabel='เหตุผลการยกเลิก';options.inputPlaceholder='ระบุเหตุผลอย่างน้อย 5 ตัวอักษร';options.preConfirm=function(value){if($.trim(value||'').length<5){Swal.showValidationMessage('กรุณาระบุเหตุผลอย่างน้อย 5 ตัวอักษร');return false;}return value;};}Swal.fire(options).then(function(r){if(!r.isConfirmed)return;var payload={_token:$('meta[name=csrf-token]').attr('content')};if(b.data('action')==='cancel')payload.reason=r.value;$.post(b.data('url'),payload).done(function(x){Swal.fire({icon:'success',text:x.msg,timer:1200,showConfirmButton:false}).then(function(){location.reload();});}).fail(function(x){Swal.fire({icon:'error',text:x.responseJSON?.message||'ดำเนินการไม่สำเร็จ'});});});});});</script>@endpush
